  async function loadSession() { if (!client) return; const { data } = await client.auth.getSession(); state.session = data.session; if (!state.session) { state.profile = null; return; } const { data: profile } = await client.from('profiles').select('id,full_name,role,must_change_password').eq('id', state.session.user.id).single(); state.profile = profile; sessionAction.classList.remove('hidden'); }
  async function loadRequests() { const { data, error } = await client.from('vacation_requests').select('id,protocol,type,status,start_date,end_date,return_date,requested_hours,created_at,notes,servidor:servidores(id,full_name,matricula,birth_date,lotacao:lotacoes(id,name),cargo:cargos(id,name),funcao:funcoes(id,name),time_bank_accounts(declared_minutes,validated_minutes),time_bank_entries(id,minutes,description,occurred_on,validated,request_id)),periods:request_periods(*),approvals:request_approvals(id,stage,decision,notes,decided_at,decided_by:profiles(full_name)),status_history:request_status_history(id,previous_status,new_status,notes,occurred_at,actor:profiles(full_name))').order('created_at', { ascending: false }); if (error) throw error; state.requests = data || []; }
