  async function updateApproval(stage, decision) { const notes = document.querySelector('#decision-notes').value.trim(); if (decision === 'rejeitada' && !notes) return showToast('Informe a justificativa da rejeição.'); const { error } = await client.rpc('decide_request_approval', { target_request_id: state.selected.id, target_stage: stage, target_decision: decision, target_notes: notes || null }); if (error) return showToast(error.message); showToast(decision === 'aprovada' ? 'Etapa aprovada.' : 'Etapa rejeitada.'); state.route = 'dashboard'; await renderDashboard(); }
